INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Addressee of the management representation letter
(1, 'Written Representations', 'Under AU-C 580, to whom is the management representation letter addressed?', '["The auditor (engagement partner or firm)", "The board of directors", "The Securities and Exchange Commission", "The entity''s external legal counsel"]'::jsonb, 0, 'AU-C 580.15 requires that the written representations be addressed to the auditor. The letter is directed to the engagement partner or the audit firm because the auditor is the party relying on these representations as audit evidence. In contrast, the board of directors may receive a separate communication about control deficiencies, but the representation letter itself is addressed exclusively to the auditor.', 'easy', 1),

-- Q2: medium / L2 — Completeness representation in practice
(1, 'Written Representations', 'During the audit of Lakewood Electronics for the year ended December 31, 2025, the engagement team at Stanton & Blair CPA discovers that management omitted a $45,000 warranty accrual from the draft financial statements. Management corrects the omission. Under AU-C 580, the representation letter should still include a statement that management has:', '["Provided the auditor with access to all relevant information", "Agreed to pay for additional audit procedures", "Waived confidentiality over all internal communications", "Authorized the auditor to contact regulatory agencies"]'::jsonb, 0, 'AU-C 580.11 requires management to represent that it has provided the auditor with all relevant information and access as agreed in the engagement letter terms. This completeness representation is required regardless of whether misstatements were found and corrected. In contrast, agreeing to pay for additional procedures relates to engagement economics, not the standard representations required by AU-C 580.', 'medium', 2),

-- Q3: medium / L2 — Representation about uncorrected misstatements
(1, 'Written Representations', 'During the audit of Greenfield Manufacturing for the year ended December 31, 2025, the engagement team at Hartley & Cole identifies three uncorrected misstatements totaling $18,000, which are individually and in aggregate immaterial. Under AU-C 580, the management representation letter should include a statement that management:', '["Has reviewed all open purchase orders for completeness", "Has implemented all internal control recommendations", "Believes the effects of uncorrected misstatements are immaterial to the financial statements", "Agrees to correct all identified misstatements before issuing statements"]'::jsonb, 2, 'AU-C 580.11 requires management to acknowledge that it believes the effects of uncorrected misstatements aggregated by the auditor are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of these items is typically attached. Unlike implementing control recommendations, which is a separate remediation activity, this representation specifically addresses management''s judgment about the materiality of passed adjustments.', 'medium', 2),

-- Q4: medium / L2 — Representation about internal control design and implementation
(1, 'Written Representations', 'The engagement team at Barrington & Wells completes fieldwork for Oakmere Corp.''s December 31, 2025 audit. The partner prepares the management representation letter and considers which representations AU-C 580 requires regarding internal control. Management should acknowledge responsibility for:', '["Testing the operating effectiveness of all key controls annually", "The design, implementation, and maintenance of internal control relevant to financial reporting", "Certifying that all internal control deficiencies have been fully remediated", "Reporting directly to shareholders on internal control effectiveness"]'::jsonb, 1, 'AU-C 580.11 requires management to acknowledge its responsibility for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of the financial statements. In contrast, testing control effectiveness annually is a procedure the auditor may perform, not a management representation requirement. Similarly, certifying full remediation goes beyond what the standard requires.', 'medium', 2),

-- Q5: easy / L1 — Oral vs. written form requirement
(1, 'Written Representations', 'Why does AU-C 580 require management representations to be in written form rather than oral form?', '["Oral representations are prohibited during the audit", "Written form is less costly for the audit firm to obtain", "Written representations reduce misunderstandings and provide documentary evidence", "Oral representations are only acceptable in reviews"]'::jsonb, 2, 'AU-C 580.A3 explains that written representations reduce the possibility of misunderstandings between management and the auditor. A written letter provides documentary audit evidence, which is more reliable than oral representations. In contrast, oral representations are routinely used during inquiry procedures throughout the audit but do not substitute for the formal written confirmation required by the standard.', 'easy', 1),

-- Q6: easy / L1 — Period covered by written representations
(1, 'Written Representations', 'What period do management''s written representations typically cover under AU-C 580?', '["Only the final quarter of the fiscal year", "The three most recent fiscal years", "All periods referred to in the auditor''s report", "Only the interval since the prior audit report date"]'::jsonb, 2, 'AU-C 580.14 states that the written representations should cover all periods referred to in the auditor''s report. If the auditor''s report covers the financial statements for the year ended December 31, 2025, the representations cover that full period. Unlike limiting coverage to the final quarter or the interval since the last audit, the standard requires representations spanning every period on which the auditor is opining.', 'easy', 1),

-- Q7: medium / L2 — Contradictory evidence discovered after representations obtained
(1, 'Written Representations', 'While completing the audit of Summit Healthcare Services for the year ended December 31, 2025, the engagement partner at Crawford & Dunn obtains the signed management representation letter. The next day, a staff auditor discovers a memo suggesting that management withheld information about a pending regulatory investigation. Under AU-C 580, the auditor should:', '["Immediately withdraw from the engagement", "Disregard the memo because the representation letter is already signed", "Evaluate the reliability of the representations and consider the effect on the audit", "Accept the representations and issue the report without changes"]'::jsonb, 2, 'AU-C 580.A24 requires the auditor to remain alert for contradictory evidence throughout the audit. If evidence suggests that one or more written representations may not be reliable, the auditor should investigate the matter, evaluate the reliability of the related representations, and consider the effect on the audit opinion. In contrast, disregarding the memo simply because the letter is already signed ignores the auditor''s ongoing professional skepticism obligation.', 'medium', 2),

-- Q8: hard / L4 — Group audit and component auditor representation letters
(1, 'Written Representations', 'Whitfield & Associates serves as the group engagement partner for the 2025 audit of Meridian Global Industries, which has three subsidiaries audited by component auditors. Each component auditor obtains a management representation letter from its respective subsidiary. The group engagement partner must determine whether the component-level representation letters are sufficient for the group audit. Under AU-C 600, the group engagement partner should:', '["Accept the component representation letters without further action", "Obtain a separate representation letter from group management covering the consolidated statements", "Request that each component auditor reissue its letter addressed to the group partner", "Require group management to cosign each component-level letter"]'::jsonb, 1, 'AU-C 600.41 requires the group engagement team to request group management to provide written representations covering the consolidated financial statements. Component-level letters address the component''s own financial information but do not cover group-level matters such as consolidation adjustments and intercompany eliminations. In contrast, simply accepting component letters without a group-level letter would leave consolidation-specific representations unaddressed.', 'hard', 4),

-- Q9: hard / L4 — Representations about accounting estimates and significant assumptions
(1, 'Written Representations', 'During the audit of Ridgeview Financial Corp. for the year ended December 31, 2025, the engagement team at Prescott & Associates evaluates a $12 million allowance for loan losses. Management used a discounted cash flow model with assumptions about default rates and recovery timing. The team considers what representations are needed regarding this estimate. Under AU-C 540 and AU-C 580, the auditor should obtain written representations that management believes:', '["The estimate needs no disclosure in the notes", "The significant assumptions used in the estimate are reasonable", "All estimates will prove accurate within 5% of actual outcomes", "The auditor bears responsibility for validating the assumptions"]'::jsonb, 1, 'AU-C 540.22 and AU-C 580.A9 indicate the auditor should obtain representations that management believes the significant assumptions used in making accounting estimates are reasonable. In contrast, the claim that estimates will prove accurate within 5% conflates representational reasonableness with predictive certainty, which the standard does not require. Responsibility for validating assumptions remains with the auditor''s procedures, not management''s representation.', 'hard', 4),

-- Q10: easy / L2 — Representation about management's responsibility for fair presentation
(1, 'Written Representations', 'First-year staff auditor Nguyen at Palmer & Associates reviews the management representation letter template for the audit of Brookdale Services. Nguyen notices a paragraph where management acknowledges its responsibility for the financial statements. Under AU-C 580, this required representation states that management is responsible for:', '["The preparation and fair presentation of the financial statements in accordance with the applicable framework", "Ensuring the auditor has sufficient time to complete all planned procedures", "Hiring qualified accounting personnel to prepare the financial statements", "Publishing the financial statements on the entity''s website within 30 days"]'::jsonb, 0, 'AU-C 580.11 requires management to represent that it has fulfilled its responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework. This foundational representation confirms the premise of the audit engagement. In contrast, ensuring sufficient audit time relates to engagement logistics, not a required representation under the standard.', 'easy', 2),

-- Q11: easy / L1 — Representation about providing access to all records
(1, 'Written Representations', 'What does the management representation letter require management to confirm regarding the auditor''s access to information?', '["That the auditor was given unlimited access to bank accounts", "That all financial records and information relevant to the audit were made available", "That the auditor reviewed every transaction during the year", "That management provided copies of all board meeting minutes"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that it has provided the auditor with all information relevant to the preparation and fair presentation of the financial statements and access to all records. In contrast, stating the auditor reviewed every transaction misstates the nature of an audit, which relies on sampling and risk-based procedures rather than examining the complete population.', 'easy', 1),

-- Q12: medium / L2 — Representation about compliance with laws and regulations
(1, 'Written Representations', 'While planning the audit of Cascade Energy Solutions for the year ended December 31, 2025, the engagement partner at Thornton & Webb reviews applicable environmental regulations that could materially affect the financial statements. Under AU-C 580, the auditor should obtain a written representation from management regarding:', '["A promise of continued compliance for the next fiscal year", "Acknowledgment that all known noncompliance with laws and regulations has been disclosed", "The entity''s complete legal history of environmental penalties", "A certification that no regulatory agency has jurisdiction over the entity"]'::jsonb, 1, 'AU-C 580.11 requires management to disclose all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing financial statements. In contrast, promising future compliance goes beyond the scope of representations because it covers prospective rather than historical matters. The standard focuses on known instances, not predictive assurances.', 'medium', 2),

-- Q13: medium / L3 — Going concern representations applied to a scenario
(1, 'Written Representations', 'During the audit of Pinehurst Retail Group for the year ended December 31, 2025, the engagement team at Wallace & Grant identifies indicators of going concern doubt, including operating losses of $3.2 million and a current ratio of 0.6. Management asserts that a planned equity injection will resolve the liquidity issue. Under AU-C 570 and AU-C 580, the auditor should obtain written representations regarding management''s:', '["Promise that the entity will not file for bankruptcy within 12 months", "Plans intended to mitigate the conditions raising substantial doubt about going concern", "Agreement to liquidate the entity if the equity injection fails", "Certification by an independent valuation firm of going concern status"]'::jsonb, 1, 'Under AU-C 570.17 and AU-C 580.A9, when substantial doubt about going concern exists, the auditor should obtain written representations regarding management''s plans to address the conditions. These representations help the auditor evaluate whether the plans are feasible and can be implemented. In contrast, a promise not to file bankruptcy is an unenforceable forward-looking commitment, not a representation about management''s remediation plans.', 'medium', 3),

-- Q14: medium / L3 — Subsequent events representation within the letter
(1, 'Written Representations', 'The audit of Haverford Corp. for the year ended December 31, 2025 is completed on March 3, 2026. On February 28, Haverford settled a significant warranty claim that existed at year-end. The engagement partner at Kessler & Pratt includes a subsequent events representation in the management representation letter. Under AU-C 580 and AU-C 560, this representation should confirm that management has disclosed all events occurring between the balance sheet date and:', '["The end of the fiscal quarter following year-end", "The date of the management representation letter", "The date the financial statements are filed with regulators", "Ninety days after the balance sheet date"]'::jsonb, 1, 'AU-C 580.A11 and AU-C 560 require management to represent that all events occurring between the balance sheet date and the date of the representation letter (which matches the auditor''s report date) have been properly reflected. In contrast, the filing date with regulators typically occurs well after the report date and would extend the representation window beyond what the standard contemplates.', 'medium', 3),

-- Q15: medium / L3 — Evaluating conflicting management representations and audit evidence
(1, 'Written Representations', 'During the audit of Aldridge Construction for the year ended December 31, 2025, the engagement team at Foster & Quinn obtains management''s representation that all related party transactions have been disclosed. However, a review of bank statements reveals a $200,000 payment to an entity owned by the CFO''s spouse that was not disclosed. Under AU-C 580, the auditor''s most appropriate response is to:', '["Accept the representation letter as sufficient because management signed it", "Investigate the payment and reassess the reliability of management representations", "Immediately issue an adverse opinion on the financial statements", "Request that management delete the related party representation from the letter"]'::jsonb, 1, 'AU-C 580.A24 states that if the auditor identifies information that is inconsistent with one or more written representations, the auditor should investigate the circumstances and reconsider the reliability of related representations. In contrast, accepting the signed letter at face value ignores the contradictory evidence and violates the auditor''s professional skepticism obligation to corroborate representations with other evidence.', 'medium', 3),

-- Q16: medium / L2 — Representation about litigation, claims, and assessments
(1, 'Written Representations', 'The engagement partner at Dunmore & Hayes drafts the management representation letter for the audit of Vanguard Property Group for the year ended December 31, 2025. Vanguard has three pending lawsuits totaling $8.5 million. Under AU-C 501 and AU-C 580, the representation letter should include management''s acknowledgment that:', '["All litigation, claims, and assessments requiring disclosure or accrual have been properly handled", "The entity will prevail in all pending legal matters", "Legal counsel has certified the outcome of all pending cases", "The auditor is responsible for identifying undisclosed litigation"]'::jsonb, 0, 'AU-C 501.12 and AU-C 580.A9 require management to represent that all known actual or possible litigation, claims, and assessments whose effects should be considered have been disclosed and appropriately accounted for. In contrast, asserting that the entity will prevail in all pending matters is a prediction of legal outcomes, which is outside the scope of representations required by the standard.', 'medium', 2),

-- Q17: hard / L3 — Requesting additional representations beyond the standard requirements
(1, 'Written Representations', 'During the audit of Westfield Biotech Corp. for the year ended December 31, 2025, the engagement team at Spencer & Crane learns that Westfield entered into a complex revenue arrangement involving milestone payments tied to FDA approval of a new drug. The standard management representation letter template does not specifically address this arrangement. Under AU-C 580, the engagement partner should:', '["Omit the topic because it is not specifically required by AU-C 580", "Request additional representations from management specific to the milestone arrangement", "Delegate responsibility for the representation to external legal counsel", "Include a general disclaimer noting the omission from the letter"]'::jsonb, 1, 'AU-C 580.A10 permits the auditor to request additional written representations beyond those required by the standard when the auditor determines they are necessary to support other audit evidence. In contrast, omitting the topic entirely would leave a gap in evidence supporting the revenue recognition treatment of a complex and material transaction, potentially undermining the sufficiency of audit evidence.', 'hard', 3),

-- Q18: hard / L4 — Representation letter for special purpose framework financial statements
(1, 'Written Representations', 'Preston & Sawyer audits the cash-basis financial statements of Elm Street Community Foundation for the year ended December 31, 2025. The foundation prepares its statements under a special purpose framework rather than GAAP. The engagement partner considers whether the management representation letter should differ from a standard GAAP audit. Under AU-C 800 and AU-C 580, the representation letter for a special purpose framework audit should:', '["Be identical to a GAAP audit representation letter with no changes", "Omit the fair presentation representation since cash basis has no such requirement", "Reference the applicable special purpose framework and confirm disclosures are adequate", "Replace the representation letter with a brief acknowledgment of engagement terms"]'::jsonb, 2, 'AU-C 800.14 and AU-C 580 require that the management representation letter for a special purpose framework audit be tailored to reference the applicable framework. Management should represent that the financial statements are prepared in accordance with the special purpose framework and that all informative disclosures are adequate. In contrast, omitting the fair presentation representation ignores that AU-C 800 still requires management to confirm presentation within the applicable framework.', 'hard', 4),

-- Q19: easy / L1 — Representation about selection and application of accounting policies
(1, 'Written Representations', 'What should the management representation letter confirm about accounting policies under AU-C 580?', '["That management selected and applied accounting policies appropriate in the circumstances", "That the auditor chose the accounting policies used in the statements", "That accounting policies remain unchanged from the prior year in all cases", "That all accounting policies comply with international standards"]'::jsonb, 0, 'AU-C 580.11 requires management to represent that it has selected and applied accounting policies that it considers appropriate in the circumstances. In contrast, the assertion that the auditor chose the accounting policies misassigns responsibility, because policy selection is exclusively a management function, not the auditor''s.', 'easy', 1),

-- Q20: medium / L3 — Representation about fair value measurements and disclosures
(1, 'Written Representations', 'During the audit of Ironwood Capital Partners for the year ended December 31, 2025, the engagement team at Norton & Hale evaluates $25 million in Level 3 fair value investments. The valuation models involve significant unobservable inputs including projected cash flows and discount rates. Under AU-C 540 and AU-C 580, the auditor should obtain management representations that the significant assumptions used in fair value measurements:', '["Have been verified by an independent pricing service", "Are reasonable and reflect management''s intent and ability to carry out specific courses of action", "Will produce valuations matching quoted market prices", "Were selected by the auditor and approved by management"]'::jsonb, 1, 'AU-C 540.22 and AU-C 580.A9 require representations that the significant assumptions used in fair value measurements are reasonable and reflect management''s intent and ability to carry out specific courses of action. In contrast, requiring verification by an independent pricing service is a substantive procedure the auditor might perform, not a management representation required by the standard.', 'medium', 3),

-- Q21: medium / L3 — Representation about completeness of contingent liabilities
(1, 'Written Representations', 'The engagement team at Fletcher & Reid completes fieldwork for the audit of Seaview Hospitality Group for the year ended December 31, 2025. Seaview operates 12 hotels and faces various potential liabilities including environmental remediation, employment disputes, and guest injury claims. The partner drafts the representation letter. Under AU-C 580 and ASC 450, the representation regarding contingencies should confirm that management has:', '["Disclosed all contingent liabilities that meet the criteria for accrual or disclosure under the applicable framework", "Obtained legal opinions on every potential claim regardless of its likelihood", "Agreed to indemnify the auditor against any undisclosed contingent liabilities", "Reserved cash equal to the maximum possible loss for each contingent liability"]'::jsonb, 0, 'AU-C 580.A9 and ASC 450 require management to represent that all contingent liabilities meeting the criteria for accrual or disclosure have been properly accounted for. This encompasses loss contingencies that are probable and estimable (accrued) as well as those that are reasonably possible (disclosed). In contrast, obtaining legal opinions on every claim regardless of likelihood would be impractical and goes beyond what the standard requires.', 'medium', 3),

-- Q22: easy / L1 — Management's knowledge as the basis for useful representations
(1, 'Written Representations', 'Under AU-C 580, written representations are requested from management because management is:', '["The party with legal authority to sign audit reports", "Responsible for the financial statements and possesses the necessary knowledge", "Required by the SEC to provide sworn testimony about the statements", "The only party permitted to communicate with the auditor"]'::jsonb, 1, 'AU-C 580.A1-A2 explains that written representations are requested from management because management is responsible for the preparation and fair presentation of the financial statements and has the knowledge of the entity''s affairs necessary to support the representations. In contrast, the auditor, not management, has the authority to sign audit reports, making that choice a misattribution of roles.', 'easy', 1),

-- Q23: hard / L4 — Updated representation letter when financial statements are reissued
(1, 'Written Representations', 'Kessler & Pratt issued an audit report on March 15, 2026 for Clearview Analytics'' December 31, 2025 financial statements. In May 2026, Clearview discovers a material error in its revenue recognition and restates its financial statements. Kessler & Pratt reissues the audit report dated July 10, 2026. Under AU-C 580 and AU-C 560, the auditor should:', '["Rely on the original March 15 representation letter without changes", "Obtain a new management representation letter dated July 10, 2026, covering the restated statements", "Request management backdate the new letter to March 15, 2026", "Waive the representation letter because the original audit was completed"]'::jsonb, 1, 'AU-C 580.15 requires the representation letter to be dated as of the date of the auditor''s report. When the auditor reissues a report on restated financial statements, a new representation letter must be obtained dated as of the new report date. In contrast, relying on the original March 15 letter would not cover the restatement period or the events discovered between March and July, leaving significant audit evidence gaps.', 'hard', 4),

-- Q24: medium / L3 — Representation about pledged or hypothecated assets
(1, 'Written Representations', 'During the audit of Redstone Logistics for the year ended December 31, 2025, the engagement team at Murray & Associates discovers that Redstone pledged its fleet of delivery vehicles as collateral for a $4.5 million line of credit. The fleet is reported at $6.2 million on the balance sheet. The engagement partner should obtain a written representation confirming that:', '["Management has no obligation to disclose pledged assets", "The auditor assumes responsibility for identifying all pledged assets", "The vehicles have been fully depreciated and removed from the books", "All assets pledged, assigned, or hypothecated as collateral have been disclosed"]'::jsonb, 3, 'AU-C 580.A9 and the applicable financial reporting framework require management to represent that all liens, pledges, or hypothecation of assets have been properly disclosed. Pledged assets affect rights and obligations assertions and require note disclosure. In contrast, claiming management has no obligation to disclose pledged assets contradicts both the representation requirements and the financial reporting framework''s disclosure standards.', 'medium', 3),

-- Q25: medium / L3 — Representation about arms-length nature of related party transactions
(1, 'Written Representations', 'The engagement team at Collins & Drake audits Riverdale Holdings for the year ended December 31, 2025. Riverdale leases office space from a partnership controlled by its CEO at $35 per square foot, while comparable market rates are $28 per square foot. Management asserts in the notes that all related party transactions were conducted on terms equivalent to arms-length transactions. Under AU-C 550 and AU-C 580, the auditor should:', '["Accept management''s assertion without further procedures since it is in the representation letter", "Obtain sufficient audit evidence to evaluate whether the arms-length assertion is supportable", "Remove the assertion from the notes and omit it from the representation letter", "Issue an adverse opinion because a related party transaction occurred"]'::jsonb, 1, 'AU-C 550.23 and AU-C 580 require that when management asserts in the financial statements that related party transactions were conducted on terms equivalent to arms-length transactions, the auditor must obtain sufficient appropriate evidence to evaluate whether the assertion is supportable. In contrast, accepting the assertion at face value without corroborating the above-market lease rate would fail to satisfy the auditor''s evidence requirements.', 'medium', 3),

-- Q26: medium / L2 — Representation about management's intent and ability (held-to-maturity)
(1, 'Written Representations', 'During the audit of Crestline Insurance Corp. for the year ended December 31, 2025, the engagement team at Douglas & Keane reviews $18 million in bonds classified as held-to-maturity at amortized cost rather than fair value. Under AU-C 580, the representation letter should include management''s confirmation of its:', '["Agreement to reclassify the bonds if the auditor requests it", "Intent and ability to hold the investments to maturity", "Projection that the bond issuers will not default before maturity", "Calculation of unrealized gains and losses for note disclosure"]'::jsonb, 1, 'AU-C 580.A9 requires representations about management''s intent and ability to carry out specific courses of action when those intentions affect classification or measurement. For held-to-maturity debt securities under ASC 320, management must represent both the positive intent and the ability to hold to maturity. In contrast, projecting that issuers will not default is a credit risk assessment, not a representation about management''s own holding intent.', 'medium', 2),

-- Q27: easy / L1 — Representation about absence of side agreements
(1, 'Written Representations', 'What representation does AU-C 580 require regarding undisclosed arrangements or agreements?', '["That management has disclosed all formal and informal side agreements that could affect the statements", "That the entity has no contracts with any third parties", "That the auditor has independently verified all contracts and agreements", "That side agreements are excluded from representation requirements"]'::jsonb, 0, 'AU-C 580.11 requires management to represent that it has disclosed all arrangements, agreements, and side agreements (whether formal or informal) that could affect the financial statements. This representation helps identify off-balance-sheet items and undisclosed commitments. In contrast, claiming the entity has no contracts at all would be an implausible assertion for any operating business and is not what the standard requires.', 'easy', 1),

-- Q28: hard / L4 — Interaction between limited representations and opinion modification
(1, 'Written Representations', 'During the audit of Ashford Pharmaceuticals for the year ended December 31, 2025, the engagement team at Pemberton & Locke requests written representations about the completeness of clinical trial liabilities. Management provides the representation letter but excludes the clinical trial liability representation, stating the amounts are uncertain. All other representations are provided, and the auditor has obtained sufficient evidence through alternative procedures for clinical trial liabilities. Under AU-C 580, the auditor should:', '["Issue an unmodified opinion because sufficient evidence was obtained through other means", "Evaluate whether the refusal affects management''s integrity and the auditor''s ability to rely on other representations", "Accept the partial letter and note the exclusion in the workpapers without further action", "Withdraw from the engagement immediately without further consideration"]'::jsonb, 1, 'AU-C 580.20 states that if management does not provide one or more requested written representations, the auditor should discuss the matter, re-evaluate management''s integrity, and evaluate the effect on the auditor''s ability to rely on other representations. In contrast, issuing an unmodified opinion solely because alternative evidence exists ignores that the refusal itself may signal broader concerns about management''s reliability and candor.', 'hard', 4),

-- Q29: medium / L2 — Representation about compensating balance arrangements
(1, 'Written Representations', 'While auditing Northgate Distribution Corp. for the year ended December 31, 2025, the engagement team at Reid & Saunders learns that Northgate maintains a $500,000 minimum balance at First National Bank as a condition of its revolving credit facility. Under AU-C 580, the representation letter should include confirmation that management has disclosed:', '["All compensating balance arrangements with financial institutions", "The interest rates earned on all bank accounts", "The names of all authorized check signers", "The total number of bank accounts maintained"]'::jsonb, 0, 'AU-C 580.A9 requires management to disclose compensating balance arrangements because they restrict the availability of cash and affect the presentation of cash and cash equivalents on the balance sheet. Compensating balances may need to be separately disclosed or reclassified as restricted cash. In contrast, disclosing interest rates on all accounts is routine banking information, not a specific representation required under the standard.', 'medium', 2),

-- Q30: easy / L1 — Representation about completeness of related party identification
(1, 'Written Representations', 'Under AU-C 580, what must management represent about related parties?', '["That the entity has no related parties of any kind", "That related party transactions need no financial statement disclosure", "That management has disclosed the identity of all related parties and all related party transactions", "That the auditor is responsible for identifying all related parties"]'::jsonb, 2, 'AU-C 580.11 and AU-C 550 require management to represent that it has disclosed the identity of all related parties and the nature of all related party relationships and transactions. In contrast, asserting the entity has no related parties is almost never accurate, as virtually every entity has owners, officers, or affiliates that meet the definition of related parties under the applicable framework.', 'easy', 1)
;

COMMIT;
